vendor_correlations.combined_query:
// Scattered Spider Identity Attack Correlation (92% semantic overlap)
let suspicious_signins = (
    SigninLogs
    | where TimeGenerated > ago(24h)
    | where ResultType == "0"
    | where RiskLevelDuringSignIn in ("high", "medium")
    | where IPAddress has_any ("tor-exit", "proxy")
    | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName
);
let mfa_attempts = (
    SigninLogs
    | where TimeGenerated > ago(24h)
    | where AuthenticationRequirement == "multiFactorAuthentication"
    | where ResultType in ("50074", "50076")
    | summarize MFAAttempts = count(), FirstMFA = min(TimeGenerated), LastMFA = max(TimeGenerated) by UserPrincipalName
    | where MFAAttempts > 5
);
suspicious_signins
| join kind=inner mfa_attempts on UserPrincipalName
| extend TimeBetween = datetime_diff('minute', TimeGenerated, FirstMFA)
| where TimeBetween between (-30 .. 30)
| project TimeGenerated, UserPrincipalName, IPAddress, Location, MFAAttempts, ThreatIndicator = "Scattered Spider Pattern"

// Scattered Spider Privilege Escalation Correlation (87% semantic overlap)
let suspicious_signins = (
    SigninLogs
    | where TimeGenerated > ago(24h)
    | where ResultType == "0"
    | where RiskLevelDuringSignIn in ("high", "medium")
    | project TimeGenerated, UserPrincipalName, IPAddress
);
let role_changes = (
    AuditLogs
    | where TimeGenerated > ago(24h)
    | where OperationName == "Add member to role"
    | extend InitiatedBy = tostring(InitiatedBy.user.userPrincipalName)
    | project TimeGenerated, InitiatedBy, TargetResources
);
suspicious_signins
| join kind=inner role_changes on $left.UserPrincipalName == $right.InitiatedBy
| extend TimeBetween = datetime_diff('minute', TimeGenerated, TimeGenerated1)
| where TimeBetween <= 60
| project TimeGenerated, UserPrincipalName, IPAddress, TargetResources, ThreatIndicator = "Privilege Escalation After Suspicious Login"

// Scattered Spider Full Attack Chain Correlation (90% semantic overlap)
let suspicious_signins = (
    SigninLogs
    | where TimeGenerated > ago(24h)
    | where ResultType == "0"
    | where RiskLevelDuringSignIn in ("high", "medium")
    | project SignInTime = TimeGenerated, UserPrincipalName, IPAddress
);
let mfa_attempts = (
    SigninLogs
    | where TimeGenerated > ago(24h)
    | where AuthenticationRequirement == "multiFactorAuthentication"
    | where ResultType in ("50074", "50076")
    | summarize MFAAttempts = count(), MFATime = min(TimeGenerated) by UserPrincipalName
    | where MFAAttempts > 5
);
let role_changes = (
    AuditLogs
    | where TimeGenerated > ago(24h)
    | where OperationName == "Add member to role"
    | extend InitiatedBy = tostring(InitiatedBy.user.userPrincipalName)
    | project RoleTime = TimeGenerated, InitiatedBy, TargetResources
);
suspicious_signins
| join kind=inner mfa_attempts on UserPrincipalName
| join kind=inner role_changes on $left.UserPrincipalName == $right.InitiatedBy
| extend 
    SignInToMFA = datetime_diff('minute', MFATime, SignInTime),
    MFAToRole = datetime_diff('minute', RoleTime, MFATime)
| where SignInToMFA <= 30 and MFAToRole <= 60
| project SignInTime, UserPrincipalName, IPAddress, MFAAttempts, TargetResources, AttackChainDetected = "Complete Scattered Spider Pattern"
